// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    Phishable c;
    function setUp() public { c = new Phishable(address(this)); }

    function testFuzz_property(uint256 initialBalance, address recipient) public {
        vm.assume(uint160(recipient) > 255 && recipient != address(this) && recipient != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && recipient != 0x000000000000000000636F6e736F6c652e6c6f67 && recipient != 0x4e59b44847b379578588920cA78FbF26c0B4956C && recipient != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);

        bound(initialBalance, 1, 1000 ether);
        vm.assume(recipient != address(this));
        vm.assume(recipient != address(c));

        vm.deal(address(c), initialBalance);
        uint256 contractBalanceBefore = address(c).balance;
        uint256 recipientBalanceBefore = recipient.balance;

        vm.prank(address(this));
        c.withdrawAll(recipient);

        uint256 recipientBalanceAfter = recipient.balance;
        assertTrue(recipientBalanceAfter == recipientBalanceBefore + contractBalanceBefore);
    }
}
